 const value=()=>{const t=toks[i++];return t?.startsWith(':')?scalar(values[t]):scalar(item[names[t]??t])};
 const atom=()=>{let t=toks[i];if(t==='('){i++;const v=or();assert.equal(toks[i++],')');return v}if(t==='attribute_exists'||t==='attribute_not_exists'){i++;assert.equal(toks[i++],'(');const name=names[toks[i]]??toks[i];i++;assert.equal(toks[i++],')');return t==='attribute_exists'?item[name]!==undefined:item[name]===undefined}const a=value(),op=toks[i++];if(op==='IN'){assert.equal(toks[i++],'(');const vals=[value()];while(toks[i]===','){i++;vals.push(value())}assert.equal(toks[i++],')');return a!==undefined&&vals.includes(a)}const b=value();if(a===undefined||b===undefined)return false;return op==='='?a===b:op==='<>'?a!==b:op==='>'?a>b:op==='<'?a<b:op==='>='?a>=b:op==='<='?a<=b:(()=>{throw Error('unknown operator '+op)})()};
